function quicksort(arr):
  if arr.length <= 1:
    return arr
  pivot = arr[0]
  less = []
  greater = []
  for i in arr[1:]:
    if i <= pivot:
      less.push(i)
    else:
      greater.push(i)
  return quicksort(less).concat(pivot).concat(quicksort(greater))
